      setTaskPriority.run(priority, task, id);
      response.writeHead(303, { Location: detailLocation(id, filter) });
      response.end();
    } else if (request.method === 'POST' && /^\/projects\/\d+\/tasks\/\d+\/rename$/.test(url.pathname)) {
